import jdk.incubator.vector.IntVector;
import jdk.incubator.vector.VectorSpecies;

public class Optimizacion {
  // Este código requiere Java 16+ y activar módulos incubadores
  static final VectorSpecies<Integer> SPECIES = IntVector.SPECIES_PREFERRED;

  public static void main(String[] args) {
      int[] x = {1, 2, 3, 4};
      int[] y = {4, 5, 6, 7};
      int[] z = new int[4];

      IntVector v1 = IntVector.fromArray(SPECIES, x, 0);
      IntVector v2 = IntVector.fromArray(SPECIES, y, 0);

      v1.add(v2).intoArray(z, 0);
      System.out.println(java.util.Arrays.toString(z));
  }
}
